/* Sources reviewed 19 November 2026. IP/daily rainfall values are not hourly limits. */
(function(root){'use strict';
const sources={mavic3m:{url:'https://enterprise.dji.com/mavic-3-m',text:'DJI Mavic 3M manufacturer guidance: do not fly in rain, snow or lightning.',noRain:true},m300:{url:'https://enterprise.dji.com/matrice-300',text:'DJI M300 RTK: IP45; do not fly in rain heavier than 100 mm/24 hr. Protection can degrade with wear. This daily rainfall statement is not a verified hourly precipitation limit.',noRain:false},mavic3:{url:'https://dl.djicdn.com/downloads/DJI_Mavic_3/DJI_Mavic_3_User_Manual_v2.2_en.pdf',text:'DJI Mavic 3 manual: do not operate in rain, snow or fog.',noRain:true},enterprise:{url:'https://enterprise.dji.com/mavic-3-enterprise?from=nav&site=enterprise',text:'DJI Mavic 3 Enterprise guidance: do not fly in rain; the series is not waterproof.',noRain:true},matrice4:{url:'https://enterprise.dji.com/matrice-4-series/faq',text:'DJI Matrice 4 Series FAQ: not waterproof; return and land as soon as possible if rain starts.',noRain:true},m350:{url:'https://enterprise.dji.com/matrice-350-rtk/faq',text:'DJI M350 RTK: IP55; do not fly in rain heavier than 100 mm/24 hr. The rating can degrade with wear. This daily rainfall statement is not a verified hourly precipitation limit.',noRain:false}};
function reference(id){if(id==='dji-mavic-3-multispectral-(3m)')return sources.mavic3m;if(id==='dji-matrice-300-rtk')return sources.m300;if(['dji-mavic-3','dji-mavic-3-cine'].includes(id))return sources.mavic3;if(['dji-mavic-3-enterprise-(3e)','dji-mavic-3-thermal-(3t)','dji-mavic-3ta','dji-mavic-3e-eu-c1-configuration','dji-mavic-3t-eu-c1-configuration'].includes(id))return sources.enterprise;if(['dji-matrice-4e','dji-matrice-4t','dji-matrice-4e-low-noise','dji-matrice-4t-low-noise'].includes(id))return sources.matrice4;if(id==='dji-matrice-350-rtk')return sources.m350;return null;}
root.FLIGHT_PRECIPITATION={reference};if(typeof module!=='undefined')module.exports={reference};if(typeof document==='undefined')return;
const el=id=>document.getElementById(id);function apply(id){if(reference(id)?.noRain)el('maxrain').value='0';}function render(){const box=el('precipitationreference');if(!box)return;const id=el('aircraftselect').value,ref=reference(id);
box.replaceChildren();const p=document.createElement('p');p.textContent=ref?ref.text:'No applicable numeric precipitation tolerance has been verified here for this aircraft/configuration. The initial 0 mm/h is a conservative dry-weather planning suggestion, not a manufacturer wet-weather rating.';box.append(p);if(ref){const a=document.createElement('a');a.href=ref.url;a.target='_blank';a.rel='noopener';a.textContent='Manufacturer precipitation guidance';box.append(a);}const note=document.createElement('p');note.className='hint';note.textContent='Use the most restrictive aircraft, payload, battery and controller requirements. An IP rating is not an hourly rainfall allowance. Precipitation probability is an operator planning threshold, not a manufacturer tolerance. Positive hourly limits require your exact approved/manual procedure; do not divide a 24-hour rainfall figure by 24.';box.append(note);}
root.flightPrecipitationApply=apply;root.flightPrecipitationReference=render;root.addEventListener('flightdesk:decision',render);render();
})(typeof window!=='undefined'?window:globalThis);
